/**
 * statWatermark.ts - 指标卡右侧的统计底纹。
 * @package @vxture/design-ui
 * @layer Presentation
 * @category Components - Pattern
 *
 * 内联成 data URI 而不是引一个文件：DS 包没有对外暴露 assets/media，各门户
 * 就得各自把图安置到自己的 public/ 下，一个装饰要靠四处复制来维持。
 *
 * **两份底纹，按有没有图标分**（owner 2026-08-06）：
 * - 不带图标的卡（头部那种重点指标）用**动图**——它没有图标，右侧这枚动的
 *   柱状图就是它唯一的视觉符号；
 * - 带图标的卡用**静图**（动图的末帧）——图标已经把语义说清楚了，再来一份
 *   常驻动画只会跟它抢。
 *
 * 静图 510 字节、动图 39KB。动图只出现在少数几张重点卡上，不是一屏十余份。
 */

export const STAT_WATERMARK_STILL =
  "data:image/gif;base64,";

export const STAT_WATERMARK_ANIMATED =
  "data:image/gif;base64,";
